
/**
 * Server-side version of the IMED automatic matching algorithm, backed by the
 * same normalization/scoring/reference rules as assets/js/app.js (matcher v4).
 * The input ledger makes sequential batches deterministic and resumable.
 * Suggestions are NOT confirmed allocations, and no IMED submission occurs.
 */
const latin=s=>String(s??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));
const num=v=>{let s=latin(v).replace(/[٬,\s]/g,'').replace(/[٫]/g,'.');let n=Number(s);return Number.isFinite(n)?n:0};
const norm=s=>latin(String(s??'').toLowerCase()).replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\s\-_/،,().]/g,'').trim();

const PRODUCT_TOKEN_CACHE=new Map(), PRODUCT_SIM_CACHE=new Map();
function productTokens(value){
 let raw=String(value||'').toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک');
 const cacheKey=raw;
 if(PRODUCT_TOKEN_CACHE.has(cacheKey))return PRODUCT_TOKEN_CACHE.get(cacheKey);
 // Normalize common Persian/English spellings used in IMED and Sepidar descriptions.
 raw=raw.replace(/ویتال ?تک|ویتالکت|ويتالكت|vital ?tec|vitaltec/g,' vitaltec ')
   .replace(/ساکشن|ساكشن|ساکشن/g,' suction ')
   .replace(/کتتر|کاتتر|کاتر/g,' catheter ')
   .replace(/تراکئوستومی|تراکستومی|تراکئوستومی/g,' tracheostomy ')
   .replace(/لوله\s*تراشه/g,' et tube ');
 const stop=new Set(['عدد','سایز','size','مدل','کالا','محصول','دستگاه','سیستم','بسته','مجموعه','with','for','and','the']);
 const result=[...new Set(raw.replace(/[^\u0600-\u06ffa-z0-9]+/g,' ').split(/\s+/).map(x=>x.trim()).filter(x=>x.length>1&&!stop.has(x)))];
 if(PRODUCT_TOKEN_CACHE.size>50000)PRODUCT_TOKEN_CACHE.clear();PRODUCT_TOKEN_CACHE.set(cacheKey,result);return result;
}
function productSimilarity(a,b){
 const x=norm(a),y=norm(b);if(!x||!y)return 0;if(x===y)return 1;if(x.includes(y)||y.includes(x))return .96;
 const key=x<y?x+'\u0001'+y:y+'\u0001'+x;if(PRODUCT_SIM_CACHE.has(key))return PRODUCT_SIM_CACHE.get(key);
 const A=new Set(productTokens(a)),B=new Set(productTokens(b));if(!A.size||!B.size)return 0;
 let common=0;A.forEach(t=>{if(B.has(t))common++});
 const score=Math.max((2*common)/(A.size+B.size),common/Math.max(1,Math.min(A.size,B.size))*.88);
 if(PRODUCT_SIM_CACHE.size>80000)PRODUCT_SIM_CACHE.clear();PRODUCT_SIM_CACHE.set(key,score);return score;
}
function dateOrderValue(v){const a=(latin(String(v||'')).match(/\d+/g)||[]).map(Number);return a.length>=3?a[0]*10000+a[1]*100+a[2]:0}
function jalaliMonthKey(v){const x=latin(String(v||'')).match(/(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})/);if(!x)return null;const y=Number(x[1]),m=Number(x[2]);return m>=1&&m<=12?y*12+m:null}

function compileDescriptors(descriptors){
 const terms=[...new Set((descriptors?.values||[]).flatMap(productTokens))];
 return {...(descriptors||{values:[]}),allTerms:terms,termSet:new Set(terms)};
}
function distinctiveScore(sepidarName,descriptors){
 if(!descriptors||!descriptors.values.length)return {score:0,matched:[],count:0,mismatch:false,sizeMatch:false};
 const target=productTokens(sepidarName),targetSet=new Set(target);
 const matched=target.filter(t=>descriptors.termSet.has(t));
 const ratio=descriptors.allTerms.length?matched.length/descriptors.allTerms.length:0;
 const targetRatio=target.length?matched.length/target.length:0;
 // Compare explicit size fields separately: a missing size in a short invoice label
 // is unknown, but an explicitly different size is a real technical mismatch.
 const sourceText=String(sepidarName||'').toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک');
 const descText=(descriptors.values||[]).join(' ').toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک');
 const sizeRx=/(?:سایز|سایز|size)\s*[:：-]?\s*(\d+(?:\.\d+)?)/g;
 const getSizes=t=>[...t.matchAll(sizeRx)].map(m=>m[1]);
 const ds=getSizes(descText),ss=getSizes(sourceText);
 const sizeMatch=ds.length>0&&ss.length>0&&ds.some(x=>ss.includes(x));
 const mismatch=ds.length>0&&ss.length>0&&!sizeMatch;
 let score=Math.min(1,Math.max(ratio,targetRatio*.9));
 if(sizeMatch)score=Math.min(1,score+.22);
 if(mismatch)score=Math.max(0,score-.55);
 // Two or more distinctive hits can validate a concise Sepidar label even when
 // it omits accessory details listed in the full IMED distinction.
 if(matched.length>=2&&!mismatch)score=Math.max(score,.42);
 return {score,matched,count:matched.length,mismatch,sizeMatch,descriptorSizes:ds,sourceSizes:ss};
}
